"use client";

import {
  createContext,
  useContext,
  useEffect,
  useRef,
  useState,
  useCallback,
  type Dispatch,
  type SetStateAction,
  type ReactNode,
} from "react";
import { usePathname } from "next/navigation";
import { getSendingActive } from "@/lib/sending-status-actions";

const SendingContext = createContext<{
  locked: boolean;
  setSubmitting: Dispatch<SetStateAction<boolean>>;
  markQueued: () => void;
} | null>(null);

export function SendingStatusProvider({
  initialSending,
  children,
}: {
  initialSending: boolean;
  children: ReactNode;
}) {
  const [sending, setSending] = useState(initialSending);
  const [submitting, setSubmitting] = useState(false);
  const version = useRef(0);
  const pathname = usePathname();
  const markQueued = useCallback(() => {
    ++version.current;
    setSending(true);
  }, []);

  useEffect(() => {
    let cancelled = false;
    let pending = false;
    const refresh = async () => {
      if (pending || document.visibilityState !== "visible") return;
      pending = true;
      const requestedVersion = version.current;
      try {
        const active = await getSendingActive();
        if (!cancelled && requestedVersion === version.current)
          setSending(active);
      } catch {
        // A failed status check must not unlock an active batch.
      } finally {
        pending = false;
      }
    };
    void refresh();
    const interval = window.setInterval(() => void refresh(), 5000);
    document.addEventListener("visibilitychange", refresh);
    window.addEventListener("focus", refresh);
    return () => {
      cancelled = true;
      window.clearInterval(interval);
      document.removeEventListener("visibilitychange", refresh);
      window.removeEventListener("focus", refresh);
    };
  }, [pathname]);

  return (
    <SendingContext.Provider
      value={{ locked: submitting || sending, setSubmitting, markQueued }}
    >
      {children}
    </SendingContext.Provider>
  );
}

export function useSendingStatus() {
  return useContext(SendingContext);
}
